{
  "root_cause": "The datepicker widget traps focus inside its popup when opened, preventing the Tab key from moving focus to the next form field. The keydown listener for the datepicker input does not allow the Tab key to bubble up, so focus remains trapped within the datepicker popup.",
  "repair_strategy": "Modify the keydown listener registration in Datepicker.js to intercept the Tab key when the datepicker is active, hide the picker, and then allow the original keydown handler to run (or simply let the browser handle Tab after hiding). This ensures that pressing Tab while the datepicker is open closes the popup and moves focus to the next focusable element (the access notes input).",
  "edits": [
    {
      "path": "js/Datepicker.js",
      "sha256": "26c130b5380a4d36ae7de5ca8e06affc4ed327048a689e12fc9a8804eb63b595",
      "before": "    const keydownListener = [element, 'keydown', onKeydown.bind(null, this)];
    if (inputField) {
      registerListeners(this, [
        keydownListener,
        [inputField, 'focus', onFocus.bind(null, this)],
        [inputField, 'mousedown', onMousedown.bind(null, this)],
        [inputField, 'click', onClickInput.bind(null, this)],
        [inputField, 'paste', onPaste.bind(null, this)],
        // To detect a click on outside, just listening to mousedown is enough,
        // no need to listen to touchstart.
        // Actually, listening to touchstart can be a problem because, while
        // mousedown is fired only on tapping but not on swiping/pinching,
        // touchstart is fired on swiping/pinching as well.
        // (issue #95)
        [document, 'mousedown', onClickOutside.bind(null, this)],
        [window, 'resize', picker.place.bind(picker)]
      ]);
    } else {
      registerListeners(this, [keydownListener]);
      this.show();
    }",
      "after": "    const datepicker = this;
    function keydownHandler(ev) {
      if (ev.key === 'Tab' && datepicker.active) {
        datepicker.hide();
      }
      onKeydown.call(datepicker, ev);
    }
    const keydownListener = [element, 'keydown', keydownHandler];
    if (inputField) {
      registerListeners(this, [
        keydownListener,
        [inputField, 'focus', onFocus.bind(null, this)],
        [inputField, 'mousedown', onMousedown.bind(null, this)],
        [inputField, 'click', onClickInput.bind(null, this)],
        [inputField, 'paste', onPaste.bind(null, this)],
        // To detect a click on outside, just listening to mousedown is enough,
        // no need to listen to touchstart.
        // Actually, listening to touchstart can be a problem because, while
        // mousedown is fired only on tapping but not on swiping/pinching,
        // touchstart is fired on swiping/pinching as well.
        // (issue #95)
        [document, 'mousedown', onClickOutside.bind(null, this)],
        [window, 'resize', picker.place.bind(picker)]
      ]);
    } else {
      registerListeners(this, [keydownListener]);
      this.show();
    }"
    }
